import re
from concurrent.futures import ThreadPoolExecutor, as_completed
from threading import Lock
from ta_emss import ta_emss

from ta_logcollector.utils.common import is_ip_addr
from ta_logcollector.settings import MAX_SUPPORTED_VMs

EMSS_HANDLERS = {
    vm_id: {"lock": Lock(), "setup_completed": False, "instance": None} for vm_id in range(1, MAX_SUPPORTED_VMs + 1)
}


def get_emss_ip(emss_ip):
    # type: (str) -> str
    """
    Iterate thru emss configuration dict and replace empty IP.

    IP address from local emssim.conf file or default one 10.0.1.1 is used.

    :param emss_cfg:
    :return:
    """
    # emss_ip = self.config['emss']['ip']
    ip_from_conf_file = get_emss_ip_from_cfg_file(cfg_file="/etc/emssim.conf")
    return emss_ip if not ip_from_conf_file or ip_from_conf_file == emss_ip else ip_from_conf_file


def get_emss_ip_from_cfg_file(cfg_file="/etc/emssim.conf"):
    # type (str) -> str
    """
    Read /etc/emssim.conf file and get emss IP address.
    If file does not exist empty string is return.:q:q

    :param cfg_file: full path to emss.conf file
    :return: EmsSim IP address
    """
    emss_ip = ""
    try:
        with open(cfg_file, "r") as emss_cfg:
            text = emss_cfg.read()
        match = re.search(r"flexi_proxy\s=\s([\d.]+):\d+", text).group(1)
        emss_ip = match if is_ip_addr(match) else ""
    except (IOError, AttributeError):
        pass
    return emss_ip


def get_emss_connection(logger, emss_connections_data, port=7000):
    # type: (Logger, dict, int) -> Generator[Tuple[ta_emss, int], None, None]
    """
    Establish connection to EMSS.
    :param logger: network logger
    :param emss_connections_data: dict of dictionaries with host and port for EmsSim
    :param port: starting port for emss - 400x for JSON RPC, 700x for logger
    :return: EmsSim connection
    """
    with ThreadPoolExecutor(max_workers=len(emss_connections_data)) as executor:
        futures = [
            executor.submit(_create_emss_connection, logger, emss_connections_data["ip"], bts_id, port)
            for bts_id in emss_connections_data["bts_ids"]
        ]
        for future in as_completed(futures):
            yield future.result()


def _create_emss_connection(logger, emss_ip, bts_id, port):
    # type: (Logger, str, int, int) -> Tuple[ta_emss, int]
    logger.debug("emss-{} for host = {} port = {}".format(bts_id, emss_ip, port + bts_id))
    logger.debug("Acquiring lock")
    with EMSS_HANDLERS[bts_id]["lock"]:
        logger.debug("Acquired lock")
        if not EMSS_HANDLERS[bts_id]["instance"]:
            EMSS_HANDLERS[bts_id]["instance"] = ta_emss(
                host=emss_ip, port=port + bts_id, bts_id=bts_id, wait_discovery=False
            )
        emss = EMSS_HANDLERS[bts_id]["instance"]
        if not EMSS_HANDLERS[bts_id]["setup_completed"]:
            emss.setup_emss(bts_id=bts_id)
            EMSS_HANDLERS[bts_id]["setup_completed"] = True
    logger.debug("Released lock")
    return emss, bts_id
